/* ================= MCQ QUESTIONS - Mathematics and Instruments - Unit 5: Instruments & Its Maintenance =================
 * One unit per file: the app loads ONLY this unit's 3 files (mcq + subjective
 * + study) when you open the unit - see js/data-manifest.js.
 *
 * HOW TO ADD A QUESTION: copy one {q, o, a, e} block, paste it after the last
 * one (with a comma between blocks), and edit the text.
 *   q = question,  o = 4 options,  a = correct option NUMBER (0, 1, 2 or 3),
 *   e = explanation shown after answering.
 * IMPORTANT: do NOT rename the unit title in square brackets - the app finds
 * questions by matching it exactly.
  *
 * RE-REVIEWED (full deep pass) 2026-09-16: every item re-checked; answer keys
 * corrected where the keyed option was wrong, unanswerable stems rewritten,
 * duplicate options rebuilt so exactly one answer is defensible, and every
 * explanation rewritten to state the reason. Item count and order unchanged.
 * ============================================================================== */

window.EXTRA = window.EXTRA || {};

window.EXTRA["Instruments & Its Maintenance"] = window.EXTRA["Instruments & Its Maintenance"] || {};
window.EXTRA["Instruments & Its Maintenance"].mcq = [
      {q:"The temporary adjustment of a theodolite at a station consists of:", o:["The two peg test", "Cleaning the lenses", "Setting up, centring, levelling and focusing", "Only removing the collimation error"], a:2, e:"Temporary adjustments are made at every station: setting up the tripod, centring over the station mark, levelling the instrument and focusing the eyepiece and object glass to remove parallax. Permanent adjustments correct instrumental errors."},
      {q:"A total station is a combination of an electronic theodolite and:", o:["A compass", "A chain", "A plane table", "An electronic distance measuring device"], a:3, e:"A total station combines an electronic theodolite for measuring angles with an EDM for measuring distances, together with an on board computer for computing and storing coordinates."},
      {q:"The instrument used for measuring horizontal and vertical angles is the:", o:["Theodolite", "Ranging rod", "Arrow", "Chain"], a:0, e:"The theodolite is the standard instrument for the precise measurement of horizontal and vertical angles in surveying."},
      {q:"The two peg test is performed to check:", o:["The centring of a theodolite", "The collimation error of a level", "The length of a chain", "The magnetic declination"], a:1, e:"The two peg test checks whether the line of collimation of a level is truly horizontal when the bubble is centred, that is, whether a collimation error exists."},
      {q:"Parallax in a telescope is removed by:", o:["Changing the tripod", "Levelling the instrument", "Proper focusing of the eyepiece and object glass", "Centring the instrument"], a:2, e:"Parallax occurs when the image does not fall exactly in the plane of the cross hairs. It is removed by first focusing the eyepiece on the cross hairs and then focusing the object glass on the object."},
      {q:"A dumpy level is used to:", o:["Establish a horizontal line of sight for levelling", "Measure horizontal angles", "Set out right angles", "Measure slopes"], a:0, e:"The dumpy level provides a horizontal sight for staff readings; angles are measured with the theodolite."},
      {q:"The function of the foot (levelling) screws is to:", o:["Centre the bubble and level the instrument", "Clamp the spindle", "Read the staff", "Focus the telescope"], a:0, e:"Foot screws tilt the tribrach to centre the plate bubble — the levelling step of temporary adjustment."},
      {q:"One small division on a metric levelling staff represents:", o:["1 cm", "5 mm", "1 dm", "1 mm"], a:1, e:"Metric staffs are figured in metres with cm graduations; the least count read directly is 5 mm."},
      {q:"The prismatic compass measures:", o:["Elevations", "Whole circle bearings", "Vertical angles", "Slopes"], a:1, e:"The prismatic compass reads whole circle bearings from magnetic north clockwise; the prism lets the observer sight the object and read the ring at the same time."},
      {q:"The Abney level is used to:", o:["Measure bearings", "Test the chain", "Measure slopes and vertical angles", "Run precise levelling"], a:2, e:"The Abney level/clinometer measures ground slopes and vertical angles quickly for reconnaissance and contour tracing."},
      {q:"After field work, surveying instruments should be:", o:["Dismantled fully", "Left in the sun", "Cleaned, dried and kept in their boxes", "Oiled heavily"], a:2, e:"Wipe moisture and dust, dry the box, loosen clamps and store safely — moisture and fungus damage optics."},
      {q:"The optical square works on the principle of:", o:["Polarisation", "Refraction", "Magnetic attraction", "Double reflection"], a:3, e:"Two reflections (horizon glass + index glass) turn the sight by exactly 90° for setting right angles."},
      {q:"A ranging rod is usually:", o:["1 m long", "5 m long", "10 m long", "2 or 3 m long"], a:3, e:"Ranging rods of 2–3 m with red-white bands mark stations and range lines."},
      {q:"How are theodolites classified based on their type?", o:["2", "3", "4", "5"], a:1, e:"Theodolites are broadly classified into three types: Vernier, Transit, and Digital/Electronic."},
      {q:"Which of the following is an integral part of the theodolite and is mounted on a spindle known as a horizontal axis?", o:["Telescope", "Index frame", "Horizontal plane Vernier", "Horizontal circle"], a:0, e:"The telescope is mounted on the horizontal (trunnion) axis so it can rotate vertically."},
      {q:"Horizontal axis is also called __________", o:["Inner axis", "Outer axis", "Trunnion axis", "Line of sight"], a:2, e:"The horizontal axis of a theodolite is mechanically referred to as the trunnion axis."},
      {q:"The vertical circle is a circular graduated arc attached to the __________ axis of the telescope.", o:["inner axis", "outer axis", "trunnion axis", "line of sight"], a:2, e:"The vertical circle is attached to the trunnion axis so it rotates with the telescope's vertical movement."},
      {q:"By means of vertical circle clamp and its corresponding __________ the telescope can be set accurately at any desired position in the vertical plane.", o:["tripod head", "focusing screw", "levelling head", "tangent screw"], a:3, e:"The tangent screw provides fine adjustment after the vertical clamp is tightened."},
      {q:"The index frame is __________ shaped frame.", o:["U", "V", "T", "A"], a:2, e:"The index frame, which holds the vertical circle and vernier, is typically T-shaped."},
      {q:"In theodolites, two standards resemble the letter __________", o:["U", "V", "T", "A"], a:3, e:"The two vertical supports (standards) that hold the trunnion axis resemble the letter A."},
      {q:"How many types of EDM instruments are there based on wavelength?", o:["2", "4", "5", "3"], a:3, e:"Based on wavelength, EDM instruments are classified into infrared, visible light, and microwave."},
      {q:"Which of the below is used up to a range of 100km?", o:["Infrared", "Microwave", "Visible range", "Ultra-violet"], a:1, e:"Microwave EDM instruments have the longest range, capable of measuring up to 100km."},
      {q:"A total station is a combination of:", o:["EDM and Theodolite", "Compass and EDM", "Electronic Theodolite and EDM", "EDM and electronic Compass"], a:2, e:"A total station integrates an electronic theodolite with an EDM in a single unit."},
      {q:"Which unit in total station processes data collected?", o:["Data collector", "EDM", "Storage system", "Microprocessor"], a:3, e:"The microprocessor is the onboard computer that processes all collected data."},
      {q:"The bubble in a total station is centralized using:", o:["Tripod", "Levelling screw", "Tangent screw", "Foot screw"], a:1, e:"The bubble is centered by adjusting the levelling (foot) screws on the tribrach."},
      {q:"Which is the latest development in a total station?", o:["High resolution", "High accuracy", "Robotic", "Automatic"], a:2, e:"Robotic total stations, which can be operated remotely, are a recent major advancement."},
      {q:"Which of the below is not an application of total station?", o:["Crime scene investigation", "Furniture manufacture", "Mining", "Archaeology"], a:1, e:"Furniture manufacturing does not typically require the precise spatial measurement of a total station."},
      {q:"How many types of EDM are there based on the reflector type?", o:["3", "5", "4", "2"], a:0, e:"Based on reflector type, there are three: standard prism, mini prism, and reflectorless."},
      {q:"What is the range of medium range EDM?", o:["<5kms", "15-25kms", "5-25kms", ">25kms"], a:2, e:"Medium-range EDM instruments generally operate within a 5 to 25 km range."},
      {q:"Each point entered in a total station is stored in:", o:["Hard discs", "Electronic books", "Data storage", "Chip"], a:2, e:"Collected points are saved in the internal data storage of the total station."},
      {q:"Transit theodolite is a theodolite whose telescope can make a complete rotation about its horizontal axis in the vertical plane by __________ Angle", o:["90°", "270°", "180°", "360°"], a:3, e:"A transit theodolite can completely rotate 360° about its horizontal axis."},
      {q:"Non transit theodolite is a theodolite whose telescope", o:["can make a complete rotation about its horizontal axis in the vertical plane by 180°angle", "can't make a complete rotation about its horizontal axis in the vertical plane by 180°angle", "can make a complete rotation about its horizontal axis in the vertical plane by 360°angle", "can't make a complete rotation about its horizontal axis in the vertical plane by 360°angle"], a:0, e:"A non-transit theodolite cannot complete a full 360° rotation; it is limited to 180°."},
      {q:"Least count of the vernier transit theodolite is", o:["10seconds", "20seconds", "20minutes", "5minutes"], a:1, e:"The standard least count (smallest measurable angle) for a vernier theodolite is 20 seconds."},
      {q:"Least count of the digital theodolite is", o:["1/10 seconds", "2seconds", "1second", "0.1minute"], a:2, e:"Modern digital theodolites typically have a least count of 1 second."},
      {q:"Which of the following is NOT a type of theodolite?", o:["Transit theodolite", "Vernier theodolite", "Railway transit theodolite", "Highway transit theodolite"], a:1, e:"⚠️ यस item को key मा विवाद छ: vernier theodolite भनेको reading system अनुसारको मान्य classification हो (transit/vernier/digital — Q14), र यसै फाइलको Q36 ले vernier लाई 'type' नै मान्छ। त्यसैले (a) लाई 'not a type' भन्न मिल्दैन। Railway/Highway transit theodolite चाहिँ साँघुरो प्रयोगगत नाम हुन्। key यथावत राखिएको छ — आफ्नो पाठ्यपुस्तक अनुसार मिलाउनुहोला।"},
      {q:"Which of the following is not a type of theodolite?", o:["vernier theodolite", "digital theodolite", "glass arc theodolite", "laser theodolite"], a:2, e:"Glass arc is not a standard classification type for theodolites."},
      {q:"Which of the following is not a part of theodolite?", o:["telescope", "clamp screws", "leveling head", "plumb bob"], a:3, e:"A plumb bob is a separate accessory, not an integral part of the theodolite itself."},
      {q:"Which of the following is not a part of theodolite?", o:["plate level", "optical plummet", "display window", "cross staff"], a:3, e:"A cross staff is a separate historical instrument, not a component of a theodolite."},
      {q:"Cross hairs can NOT be seen in which part of the theodolite?", o:["numerical key pad", "telescope", "diaphragm", "optical viewing system"], a:0, e:"Crosshairs are viewed through the telescope/diaphragm, not on the numerical keypad."},
      {q:"Optical plummet is used for", o:["the proper centering work of theodolite", "the proper centering work of dumpy level", "the proper focusing work of theodolite", "the proper focusing work of dumpy level"], a:0, e:"The optical plummet is a small telescope used to center the instrument precisely over a ground point."},
      {q:"Out of the following applications, where vernier transit theodolite is not used", o:["in construction of road bridges", "measurement of distance between the piers", "marking center to center distance between the piers", "none of these options"], a:3, e:"Vernier transit theodolites can be used for all the listed applications."},
      {q:"With the help of electronic distance meter distance on ground can be measured in the", o:["digital form", "bar code", "bar chart form", "none of these"], a:0, e:"EDM instruments measure distances electronically and display them digitally."},
      {q:"Which of the following is not a type of EDM?", o:["total stations", "distomat", "the geodimeter", "digital theodolite"], a:3, e:"A digital theodolite only measures angles, not distances, so it is not an EDM."},
      {q:"Which of the following is not a type of EDM?", o:["short range", "medium range", "long range", "very high range"], a:3, e:"EDM instruments are generally classified as short, medium, and long range."},
      {q:"The temporary adjustments of the theodolite do not include which of the following operation?", o:["centering", "leveling", "focusing", "fine adjustment"], a:3, e:"Temporary adjustments are setup procedures (centering, leveling, focusing), not permanent mechanical adjustments."},
      {q:"Short range EDM has range-", o:["up to 5 km", "upto 5 m", "up to 50 km", "upto 0.5 km"], a:0, e:"Short-range EDM instruments have a maximum range of about 5 km."},
      {q:"Medium range EDM has range-", o:["up to 10 km", "upto 100 m", "up to 50 km", "upto 100 km"], a:0, e:"Medium-range EDM instruments have a maximum range of about 10 km."},
      {q:"Long range EDM has range", o:["between 5-50 km", "upto 100 km", "greater than 50 km", "greater than 100 km"], a:3, e:"Long-range EDM instruments can measure distances greater than 100 km."},
      {q:"Short range EDM uses/emits signal in the form of-", o:["infra red light", "microwaves", "radio waves", "carrier waves"], a:0, e:"Short-range EDM instruments typically use infrared light for measurement."},
      {q:"Medium range EDM uses/emits signal in the form of-", o:["Infrared light", "Visible light", "Microwaves", "Radio waves"], a:1, e:"Carrier wave अनुसार EDM को वर्गीकरण: infrared (Distomat) = short range करिब 3–5 km, visible light (Geodimeter) = medium range करिब 25 km, microwave (Tellurometer) = long range 100 km सम्म। मूल key ले medium range मा 'microwaves' राखेको थियो, जुन long range (Q51) सँग बाझिन्थ्यो; 'Visible light' विकल्प नै थिएन, थपिएको। [testbook](https://testbook.com/question-answer/match-the-types-of-edm-instruments-with-wavelength--6a6b2d01368eaa60f8ada8af)"},
      {q:"Long range EDM uses/emits signal in the form of-", o:["infra red light", "microwaves", "radio waves", "carrier waves"], a:1, e:"Long-range EDM instruments also primarily use microwave signals."},
      {q:"Geodimeter uses/emits", o:["infra red light", "microwaves", "radio waves", "carrier waves or modulated pulses of light from tungsten filament"], a:3, e:"The Geodimeter uses modulated light waves (originally from a tungsten filament) to measure distance."},
      {q:"The electromagnetic waves used in EDM require", o:["no medium to travel", "air medium to travel", "solid medium to travel", "water medium to travel"], a:0, e:"Electromagnetic waves can propagate through a vacuum; they do not require a physical medium."},
      {q:"The LASER means", o:["light amplification by stimulated emissions of radioactivity", "light associated with stimulated emissions of radiation", "light amplification by stimulated emissions of radiation", "light affected by stimulated emissions of radiation"], a:2, e:"LASER is an acronym for Light Amplification by Stimulated Emission of Radiation."},
      {q:"Which of the following application can't be performed using LASERS?", o:["cutting of steel plates with speed", "finding the elevations between the different points in vertical plane", "laying out & controlling drilling in difficult terrain", "assessment of soil properties"], a:3, e:"Lasers are used for alignment and cutting, but not for assessing soil properties."},
      {q:"Total station consists of", o:["only EDM", "only digital theodolite", "EDM and digital theodolite built as a single unit", "none of these options"], a:2, e:"A total station is a single integrated unit combining an EDM and a digital theodolite."},
      {q:"Total station works on", o:["ni-cd battery", "graphite cell", "ac power supply", "wet cell"], a:0, e:"Total stations are typically powered by rechargeable Ni-Cd or Li-Ion batteries."},
      {q:"Modern EDM instruments are based on the principle of", o:["Measurement of phase difference in the transmitted and received radiations", "The cooperative radar", "The speed of all radiations being constant or the same", "High frequency radiations having the same speed in an medium."], a:0, e:"Modern EDM instruments measure distance by calculating the phase difference between the transmitted and received signals."},
      {q:"The range and accuracy of EDM instruments vary such that", o:["Short range instruments have better accuracy", "Short range instruments have less accuracy", "High range instruments have better accuracy", "The range and accuracy are the same for all instruments"], a:0, e:"Generally, EDM instruments with shorter ranges provide better accuracy due to lower signal attenuation."},
      {q:"A total station is", o:["A combination of an electronic theodolite and digital level", "A combination of an electronic theodolite and a tacheometer", "An electronic theodolite with levelling capabilities", "A digital theodolite combined with an EDM module"], a:3, e:"A total station is fundamentally an integrated digital theodolite and EDM."},
      {q:"A total station can measure", o:["Distance electronically", "Horizontal angles accurately", "Vertical angles and distance", "Horizontal and vertical angles and distances"], a:3, e:"A total station is capable of measuring both horizontal and vertical angles, as well as distances."},
      {q:"A smart station is", o:["A total station with software to calculate and display many quantities", "A total station with an integrated GPS module", "With display units on both sides", "A total station attached to a computer"], a:1, e:"A smart station typically refers to a total station that has a GPS receiver integrated into it."},
      {q:"A theodolite is often designed by", o:["Diameter of the objective lens", "Diameter of the horizontal circle", "Diameter of the eye piece lens", "Length of the telescope"], a:1, e:"Theodolites are often classified by the diameter of their horizontal circle (e.g., 3.5-inch)."},
      {q:"To change the reading on the circle while measuring an angle", o:["Upper clamp is tightened and lower clamp is loosed", "Upper clamp is loosened and lower clamp is tightened", "Both upper and lower clamps are loosened", "Both upper and lower clamps are tightened"], a:1, e:"To change the reading, loosen the upper clamp to rotate the upper plate while the lower clamp holds the base."},
      {q:"The horizontal circle of a theodolite is graduated in", o:["The quadrantal system from 0 to 90 in the four quadrants", "The whole circle system from 0 to 360", "The semi circle system from 0 to 180 in the right and left halves", "A way similar to that in a prismatic compass"], a:1, e:"Horizontal circles are typically graduated from 0 to 360°."},
      {q:"The Vertical circle of a theodolite is graduated in", o:["The quadrantal system from 0 to 90 in the four quadrants", "The whole circle system from 0 to 360", "The semi circle system from 0 to 180 in the right and left halves", "A way similar to that in a prismatic compass"], a:0, e:"Vertical circles are often graduated 0-90° in quadrants to simplify angle calculations."},
      {q:"When you transit the telescope, you rotate the telescope about", o:["The vertical axis", "The trunnion axis", "The optical axis of the telescope", "The line of collimation"], a:1, e:"Transiting means rotating the telescope 180° about its horizontal (trunnion) axis."},
      {q:"A face left or normal position of observation means", o:["The vertical circle of the instrument is on the left of the observer", "The vertical circle is on the right side of the observer", "The station being observed is to the left of the observer", "The left side vernier is read for the angle value"], a:0, e:"Face left means the observer is looking through the telescope with the vertical circle on their left."},
      {q:"Focussing the objective lens is an operation done", o:["To get the cross hairs to clear view", "Every time to focus the object being sighted", "For reading the vernier clearly", "For reading vertical angles"], a:1, e:"The objective lens must be refocused for every object at a different distance to get a clear image."},
      {q:"In the method of repetition for measuring horizontal angles, to rotate the instrument without changing the reading", o:["Lower clamp screw is tightened and upper clamp is loosened", "Lower clamp screw is loosened and upper clamp is tightened", "Any one of the clamp screw is loosened", "Both the clamp screws are loosened"], a:1, e:"To rotate the entire instrument without changing the angle reading, the upper clamp must be tight and the lower clamp loosened."},
      {q:"In a theodolite", o:["The telescope axis is perpendicular to transit axis", "The axis of rotation is perpendicular to transit axis", "The telescope axis, the transit axis and the rotation axis pass through the centre of theodolite", "All the above"], a:3, e:"These are the fundamental geometric conditions for a perfectly adjusted theodolite."},
      {q:"A theodolite is said to be in perfect adjustment if", o:["Rotation axis is vertical to the transit axis", "Transit axis is perpendicular to line of collimation", "Line of collimation sweeps out a vertical plane while the telescope is elevated or depressed", "All the above"], a:3, e:"All these conditions must be met for a theodolite to be in perfect adjustment."},
      {q:"Diaphragm of a surveying telescope is held inside", o:["Eye-piece", "Objective", "Telescope tube at its mid point", "Telescope at the end nearer the eye-piece"], a:3, e:"The diaphragm with the crosshairs is located near the eyepiece end of the telescope."},
      {q:"Centering error of a theodolite produces an error", o:["In all angles equally", "Which does not vary with the direction or pointing", "Which varies with the direction of pointing and inversely with the length of sight", "None of these"], a:2, e:"Centering error causes angular error that increases with shorter sight distances and varies depending on direction."},
      {q:"LCD in the control panel of a total station stands for:", o:["Light control device", "Liquid crystal display", "Light centred device", "Lasting calibrated device"], a:1, e:"LCD = Liquid Crystal Display — total station को control panel/display मा प्रयोग हुने स्क्रिन।"},
      {q:"EDM in a total-station measures directly:", o:["vertical angles", "horizontal angles", "slope distances", "horizontal distances"], a:2, e:"EDM ले सिधै slope distance नाप्छ (instrument देखि reflector सम्मको ढल्केको दूरी)। Horizontal/vertical distance total station को microprocessor ले पछि गणना गर्छ।"},
      {q:"A total station displays:", o:["slope distances", "horizontal distances", "gradients", "contours"], a:1, e:"A total station displays horizontal distances."},
      {q:"Geotronics union in total station is:", o:["visible light device", "communication device", "special reflector", "battery system"], a:1, e:"The Geotronics union is a communication device."},
      {q:"Laser plumet in total-station is used for:", o:["centring", "levelling", "orientation", "bisection of point sighted"], a:0, e:"Laser plummet ले यन्त्रलाई ground station माथि केन्द्रित (centring) गर्न सहयोग गर्छ — लेजर बिन्दुले station mark देखाउँछ। Optical plummet को आधुनिक रूप।"},
      {q:"Theodolite प्रयोग गरि कुनै survey line को zenithal angle पद्दा left र right face मा लिईएको reading हरुको sum 400 grade हुनु पर्नेमा सो भन्दा कम वेशी भएमा त्यस्तो error लाई के भनिन्छ ?", o:["Collimation error", "Graduation error", "Index Error", "zero error"], a:2, e:"Zenithal angle को left र right face को sum 400 grade हुनुपर्नेमा फरक आएमा त्यसलाई Index Error भनिन्छ।"},
      {q:"Slope distance L र zenithal angle Z भए Horizontal distance कति होला ?", o:["L × sin Z", "L × cos Z", "L × cot Z", "L × tan Z"], a:0, e:"Zenith angle Z माथिल्लो ठाडो दिशाबाट नापिन्छ। H = L sin Z, V = L cos Z। (Vertical angle α को हकमा H = L cos α हुन्छ — भ्रम नगर्नुहोला।) मूल विकल्पहरू ('/SinZ' आदि) अपूर्ण/बिग्रिएका थिए।"},
      {q:"Tellurometer वाट कति सम्मको दुरी नापी गर्न सकिन्छ ?", o:["10km", "100 km", "50 km", "200km"], a:1, e:"Tellurometer बाट 100 km सम्मको दुरी नापी गर्न सकिन्छ।"},
      {q:"Tellurometer को आविष्कार कहिले भएको हो ?", o:["सन १९५०", "सन १९५७", "सन १९४५", "सन १९६०"], a:1, e:"Tellurometer (microwave EDM) को आविष्कार सन् १९५७ मा दक्षिण अफ्रिकामा Dr. T.L. Wadley ले गरेका थिए।"},
      {q:"Theodolite वाट zenithal angle पढ्दा left र right face को angle को sum कति हुनु पर्छ ?", o:["180°", "360°", "90°", "0°"], a:1, e:"Zenithal angle को left र right face को sum 360° हुनुपर्छ।"},
      {q:"यन्त्रको शुष्कता लागि प्रयोग गरिने silicagel को color कस्तो हुन्छ ?", o:["white", "Pink", "Red", "Blue"], a:3, e:"Silica gel (desiccant) सुक्खा अवस्थामा नीलो (blue) हुन्छ; ओसिलो सोस्दै गएपछि गुलाबी (pink) हुन्छ — तब बदल्नु/तताउनु पर्छ। यन्त्रको बाकसमा यसले optics लाई fungus/moisture बाट बचाउँछ।"},
      {q:"Subtense bar बाट नापिएको दुरी कस्तो हुन्छ ?", o:["Always horizontal हुन्छ", "Slope हुन्छ ।", "Always vertical हुन्छ", "None of above"], a:0, e:"Subtense bar (ठूलो 'Substance bar' होइन — टाइपो सुधार) बाट नापिएको दुरी horizontal हुन्छ: D = (S/2) cot(θ/2), जहाँ S = bar को लम्बाइ र θ = subtended angle।"},
      {q:"Which of the following is used for angular measurement ?", o:["Theodolite", "Sectant", "Abney’s level", "All"], a:3, e:"माथिका सबै यन्त्रहरु angular measurement का लागि प्रयोग गरिन्छ।"},
      {q:"Line of collimation र axis of telescope को relation कस्तो हुनुपर्छ ?", o:["Parallel", "Perpendicular", "Independent", "Coinciding"], a:3, e:"Line of collimation र axis of telescope Coinciding हुनुपर्छ।"},
      {q:"The colour of silicagel is", o:["White", "Pink", "Blue", "Red"], a:2, e:"Silica gel को colour नीलो (blue) हुन्छ — ओस सोसेपछि pink हुन्छ। (Q85 को दोहोरो।)"},
      {q:"Theodolite को प्रयोग गर्दा centering भयो कि भएन भनेर के ले हेरिन्छ ?", o:["Telescope", "Optical plummet", "Optical squre", "Bubble"], a:1, e:"Optical plummet ले centering भयो कि भएन हेरिन्छ।"},
      {q:"कुन Area computation गर्ने यन्त्र हो ?", o:["टायल", "Computing scale", "Planimeter", "All"], a:3, e:"माथिका सबै Area computation गर्ने यन्त्र हुन्।"},
      {q:"Optical square मा दुईवटा mirror को surface बिचको कोण कति हुन्छ ?", o:["45⁰", "50⁰", "90⁰", "120⁰"], a:0, e:"Optical square मा दुई ऐना बीच 45° को कोण हुन्छ — double reflection ले sight लाई 90° घुमाउँछ (Q209), जसले right angle set गर्न सजिलो हुन्छ।"},
      {q:"तलका मध्ये कुन यन्त्र कोण नाप प्रयोग गरिदैन ?", o:["Surveyors compass", "Theodolite", "EDM", "Total station"], a:2, e:"EDM ले दूरी मात्र नाप्छ, कोण नाप्दैन। Theodolite, surveyor's compass र total station ले कोण नाप्छन्।"},
      {q:"Mine survey मा प्रयोग हुने theodolite कुन हो ?", o:["Mining theodolite", "Gyro theodolite", "Pentax theodolite", "Wild theodolite"], a:1, e:"Mine survey (भूमिगत) मा Gyro theodolite प्रयोग गरिन्छ — यसले आफैं true north (gyroscopic) पत्ता लगाउँछ, जहाँ magnetic compass ले काम गर्दैन।"},
      {q:"Subtense bar ले नाप्ने दुरी कस्तो हुन्छ ?", o:["Horizontal", "Vertical", "Slope", "None"], a:0, e:"Subtense bar ले horizontal distance नाप्छ (D = S/2 cot θ/2) — पहाडी/undulated area मा चेनिङ गर्न नसकिने ठाउँमा उपयोगी।"},
      {q:"Optical square is based on the principle of :", o:["double refraction", "reflection", "refraction", "double reflection"], a:3, e:"Optical square double reflection को सिद्धान्तमा चल्छ — दुई ऐनाबाट फर्किएर sight 90° मा मोडिन्छ।"},
      {q:"Size of a theodolite is specified by", o:["the length of telescope", "the diameter of vertical circle", "the diameter of lower plate", "the diameter of upper plate"], a:2, e:"Theodolite को size (जस्तै 3.5-inch theodolite) lower plate (horizontal circle) को diameter ले जनाइन्छ।"},
      {q:"Clinometer को reading के हुन्छ ?", o:["sinθ", "cosθ", "tanθ", "cotθ"], a:2, e:"Clinometer को reading tanθ (gradient को रूपमा) हुन्छ — ढलानको कोण सिधै gradient/percent मा पढिन्छ।"},
      {q:"Theodolite प्रयोगबाट कुनै survey line को zenithal angle 120ᵍ आयो भने त्यसको vertical angle कति हुन्छ ?", o:["+30ᵍ", "-30ᵍ", "+20ᵍ", "-20ᵍ"], a:3, e:"Zenithal angle Z = 120ᵍ भए vertical angle α = 100ᵍ − Z = 100 − 120 = −20ᵍ। (Positive α = elevation, negative = depression।)"},
      {q:"In a theodolite adjustment process, which one is odd ?", o:["setting over the station", "leveling up the instrument", "Remove the eccentricity", "Elimination of parallax"], a:3, e:"Setting over station, levelling up र removing eccentricity — तीनै permanent adjustment हुन्; elimination of parallax भनेको focusing (temporary adjustment) हो, त्यसैले यो 'odd' हो।"},
      {q:"Surveying equipment लाई moisture को असरबाट बचाउन के गर्नुपर्छ ?", o:["घाममा सुकाउने", "कपडाले पुछ्ने", "Silica gel को प्रयोग गर्ने", "बन्द बाकसमा राख्ने"], a:2, e:"यन्त्रलाई moisture बाट बचाउन silica gel (desiccant) प्रयोग गरिन्छ — यसले ओस सोस्छ र optics मा fungus हुन दिँदैन। घाममा सुकाउनु वा भिजेको कपडाले पुछ्नु हुँदैन।"},
      {q:"तलका मध्ये कुन level को लागि bar-coded staff प्रयोग गरिन्छ ?", o:["Dumpy", "Automatic", "Digital", "Tilting"], a:2, e:"Bar-coded staff digital level सँग प्रयोग गरिन्छ — level ले bar code पढेर स्वतः staff reading र distance निकाल्छ (आँखले पढ्नु पर्दैन)।"},
      {q:"total station मा के हुँदैन ?", o:["theodolite", "EDM", "clinometer", "computer."], a:2, e:"Total station मा electronic theodolite, EDM र microprocessor/ computer हुन्छ; clinometer हुँदैन (ढलान यसले angle बाट गणना गर्छ)।"},
      {q:"which is odd-", o:["planimeter", "Telurometer", "Computing scale", "grid"], a:1, e:"Planimeter, computing scale र grid — तीनै नक्सा/क्षेत्रफलसँग सम्बन्धित छन्; Tellurometer (microwave EDM) दूरी नाप्ने यन्त्र हो, त्यसैले अमिल्दो।"},
      {q:"The angle between two mirror’s surfaces of optical square is-", o:["45°", "60°", "50°", "90°"], a:0, e:"Optical square का दुई ऐना बीच 45° को कोण हुन्छ। ⚠️ मूल item मा '45ᵍ' key गरिएको थियो — 45 ᵍ (grad) = 40.5° मात्र हुन्छ र यसै फाइलका Q92, Q136, Q195 (सबै 45°) सँग बाझिन्थ्यो; ᵍ चिह्न OCR/टाइपो देखिन्छ। डिग्रीमा स्पष्ट पारिएको।"},
      {q:"Which of the following is the most precise theodolite ?", o:["Wild T₁₆", "Wild T₁₄", "Wild T₃", "Wild T₂"], a:2, e:"Wild T₃ सबैभन्दा शुद्ध (precise) theodolite मानिन्छ — यो geodetic theodolite हो, जसले 0.2″ सम्म पढ्न सक्छ। T₁₆ भने lowest-order (1 minute) survey को लागि हो।"},
      {q:"Total station को प्रयोग गरि नापीएको दुरी कस्तो हुन्छ ?", o:["Horizontal", "vertical", "slope", "All of above"], a:3, e:"Total station ले slope distance नाप्छ र onboard microprocessor ले horizontal distance, vertical distance, height difference, coordinates — सबै गणना गरेर देखाउन सक्छ।"},
      {q:"Line of collimation र axis of telescope को सम्बन्ध कस्तो हुन्छ ?", o:["Parallel", "perpendicular", "coinciding", "independent"], a:2, e:"Line of collimation (cross-wire को intersection र objective को optical centre जोड्ने रेखा) र axis of telescope (objective र eye-piece को optical centre जोड्ने रेखा) आपसमा coincide हुनुपर्छ। (यसै फाइलको Q204 ले 'perpendicular' भन्थ्यो — सुधार गरिएको।)"},
      {q:"Theodolite वाट zenithal angle पढ्दा left र right face को angle को sum कति हुनुपर्छ", o:["180⁰", "360⁰", "90⁰", "0⁰"], a:1, e:"Zenithal angle को left face र right face reading को योग 360° (वा 400ᵍ) हुनुपर्छ। भिन्नता आएमा index error = (360° − (L+R))/2 — mean ले error हटाउँछ।"},
      {q:"सबटेन्सबारको प्रयोग गरि दुरी नापी गर्दा सब्टेन्सबार र सर्मै लाईनको सम्बन्ध कस्तो हुनुपर्छ ?", o:["Coincide", "Perpendicular", "Parallel", "जस्तो भए पनि हुन्छ।"], a:1, e:"सबटेन्सबार र सर्मै लाईन Perpendicular हुनुपर्छ।"},
      {q:"Theodolite ले", o:["Horizontal angle measure गर्छ", "Vertical angle measure गर्छ", "Zenithal angle measure गर्छ", "माथिका सबै"], a:3, e:"Theodolite ले Horizontal, Vertical र Zenithal angle सबै measure गर्छ।"},
      {q:"EDM instrument ले दुई बिन्दु विचको दुरी नाप्दा कुन आधारमा नापिन्छ ?", o:["EDM यन्त्रबाट Reflector राखेको बिन्दुसम्म पुग्ने light wave का आधारमा", "EDM यन्त्रबाट Reflector राखेको बिन्दुसम्म पुग्ने समयका का आधारमा", "EDM यन्त्रबाट पठाएको light wave लाई Reflector राखेको बिन्दुबाट फर्काउन लाग्ने समयका आधारमा", "माथिको कुनैपनि होईन"], a:2, e:"EDM यन्त्रबाट पठाएको light wave लाई Reflector राखेको बिन्दुबाट फर्काउन लाग्ने समयका आधारमा दुरी नापिन्छ।"},
      {q:"Total station is the combination of", o:["EDM only", "Theodolite only", "EDM and Theodolite", "None"], a:2, e:"Total station EDM and Theodolite को combination हो।"},
      {q:"Which of the following is true in case of theodolite adjustment ?", o:["The vertical axis should be truly vertical and at right angles to the plate bubble", "The line of collimation of the telescope should be at right angles to the transit axis", "The transit axis should be at right angles to the vertical axis of the instrument", "All of the above"], a:3, e:"माथिका सबै theodolite adjustment का लागि सही छन्।"},
      {q:"EDM ले कस्तो दुरी नाप्छ ?", o:["Horizontal", "Vertical", "Zenithal", "Slope"], a:3, e:"EDM ले slope distance नाप्छ (instrument देखि reflector सम्मको सिधा ढल्केको दूरी)।"},
      {q:"आधुनिक Theodolite मा कुन चाहिँ Telescope प्रयोग गरिन्छ ?", o:["External focusing", "Internal focusing", "क र ख दुवै", "कुनै पनि होइन"], a:1, e:"आधुनिक theodolite मा internal focusing telescope हुन्छ — focusing lens telescope भित्रै सर्छ, त्यसैले telescope को लम्बाइ स्थिर रहन्छ र parallax/wear कम हुन्छ।"},
      {q:"तलका मध्ये कुन सबै भन्दा शुद्ध मानिन्छ ?", o:["Chain Survey", "Compass Survey", "Plain Survey", "Total Station Survey"], a:3, e:"Total Station Survey सबैभन्दा शुद्ध मानिन्छ — यसले angle र distance दुवै electronically नाप्छ र computation error पनि हुँदैन।"},
      {q:"सबै भन्दा शुद्ध Level Machine कुन हो ?", o:["Total Station", "Hand level", "tilting level", "Auto level"], a:0, e:"Level को कामको लागि पनि Total Station सबैभन्दा शुद्ध उपकरण मानिन्छ (trigonometric levelling बाट), यद्यपि precise spirit levelling को विकल्पका रूपमा digital/auto level छिटो हुन्छ।"},
      {q:"Clinometer कुन प्रयोजनका लागि प्रयोग गरिन्छ ?", o:["Horizontal angle measure गर्न", "Vertical angle measure गर्न", "माथिका दुवै", "Distance Measure गर्न"], a:1, e:"Clinometer ठाडो कोण (vertical angle/slope) नाप्न प्रयोग गरिन्छ — तेर्सो कोण theodolite ले।"},
      {q:"EDM सर्वप्रथम कहिले आविष्कार भयो ?", o:["1910", "1920", "1940", "1950"], a:2, e:"EDM को विकास सन् 1940 को दशकमा सुरु भयो (Geodimeter, Sweden — 1948; Tellurometer — 1957)। ⚠️ 'पहिलो आविष्कार' को वर्ष स्रोत अनुसार फरक पर्न सक्छ।"},
      {q:"Line of collimation भन्नाले के बुझिन्छ ?", o:["Optical र eye piece को centre जोड्ने रेखा", "Eye piece को centre र diaphragm को cross-wire जोड्ने रेखा", "Objective को centre र diaphragm को cross-wire जोड्ने रेखा", "None of the above"], a:2, e:"Objective को centre र diaphragm को cross-wire जोड्ने रेखा"},
      {q:"Vertical axis मा Theodolite लाई Horizontal plane मा घुमाउने कार्यलाई के भनिन्छ ?", o:["Traversing", "Swinging", "Transiting", "Centering"], a:1, e:"Vertical axis वरिपरि horizontal plane मा theodolite घुमाउनुलाई Swinging भनिन्छ; telescope लाई trunnion axis मा पल्टाउनुलाई Transiting भनिन्छ।"},
      {q:"Clinometer को reading कुन value हो ?", o:["cot", "tan", "sine", "cos"], a:1, e:"Clinometer को reading tan θ (gradient) मा हुन्छ — सिधा slope percent/gradient पढिन्छ।"},
      {q:"डिजिटल प्रविधिबाट नाप नक्सा हुने क्षेत्रमा टोटल स्टेसनमा संकलन हुने डाटालाई कुन format मा set गरिन्छ ?", o:["Easting, Northing, Elevation, Remark", "Northing, Easting, Elevation, Remark", "Northing, Easting, Remark, Elevation", "जुन गरेपनि हुन्छ"], a:0, e:"Total station मा data सामान्यतया Easting, Northing, Elevation, Remark — यही क्रममा set गरिन्छ (point id, code सहित)।"},
      {q:"Theodolite मा धेरै सेट पढ्दा कुन त्रुटी कम हुन्छ ?", o:["collimation error", "Index error", "graduation error", "माथिका सबै error"], a:2, e:"धेरै set मा reading लिँदा graduation error (circle को graduation मा भएको irregularity) कम हुन्छ — बिभिन्न भागमा पढिँदा error औसत हुन्छ। Collimation/index error भने face left–right बाट हट्छ।"},
      {q:"A clinometer is used for", o:["Measuring angle of slope", "Correcting line of collimation", "Setting out right angles", "Defining natural features"], a:0, e:"Clinometer ढलानको कोण (angle of slope) नाप्न प्रयोग गरिन्छ — line of collimation सीधा गर्ने, right angle set गर्ने वा natural feature छुट्याउने यसको काम होइन।"},
      {q:"Pick up the correct statement from the following :", o:["Box sextant is used for the measurement of horizontal angles", "Gradiometer is used for setting out any required gradient", "Line ranger is used for locating intermediate stations on a survey line", "All the above"], a:3, e:"तीनै कथन सही: Box sextant ले तेर्सो कोण, Gradiometer ले आवश्यक gradient set गर्न, Line ranger ले survey line मा मध्यवर्ती station भेट्न काम गर्छ।"},
      {q:"The bubble tube is nearly filled with", o:["Alcohol or chloroform", "A liquid which is very mobile", "A liquid having low freezing point", "All the above"], a:3, e:"Bubble tube मा alcohol/chloroform जस्ता धेरै मोबाइल (mobile), कम freezing point भएको तरल भरिएको हुन्छ — जसले bubble छिटो स्थिर हुन्छ र जाडोमा जम्दैन।"},
      {q:"Theodolite मा line of collimation र Horizontal axis को सम्बन्ध कस्तो हुन्छ ?", o:["एक आपसमा Perpendicular", "एक आपसमा parellel", "एक आपसमा coincide", "एक आपसमा सम्बन्ध हुँदैन"], a:0, e:"Theodolite मा line of collimation र horizontal (trunnion) axis आपसमा perpendicular (90°) हुनुपर्छ — नभए collimation error आउँछ।"},
      {q:"Cross hairs in surveying telescopes, are fitted", o:["In the objective glass", "At the centre of the telescope", "At the optical centre of the eye piece", "In front of the eye piece"], a:3, e:"Cross hairs diaphragm मा, eye-piece को अगाडि (in front of the eye-piece) फिट गरिएका हुन्छन् — जसले गर्दा focusing गर्दा object को real image cross-hair को plane मै पर्छ।"},
      {q:"EDM को accuracy कति हुन्छ ?", o:["per part million", "part per million", "part per thousand", "per part thousand"], a:1, e:"EDM को accuracy part per million (ppm) मा व्यक्त गरिन्छ — जस्तै ±(5 mm + 1 ppm)।"},
      {q:"Clinometers कुन value पढ्न प्रयोग गरिन्छ ?", o:["Sin", "Cos", "Tangent", "Cot"], a:2, e:"Clinometer ले tangent (tan θ) value पढ्छ — gradient सिधा पढिन्छ।"},
      {q:"Theodolite मा line of collimation र altitude level axis को सम्बन्ध कस्तो हुन्छ ?", o:["एक आपसमा Perpendicular", "एक आपसमा parellel", "एक आपसमा coincide", "एक आपसमा सम्बन्ध हुँदैन"], a:0, e:"Line of collimation र altitude level axis आपसमा perpendicular हुनुपर्छ।"},
      {q:"The construction of optical square is based, on the principle of optical", o:["Reflection", "Refraction", "Double refraction", "Double reflection"], a:3, e:"Optical square को बनावट optical double reflection मा आधारित छ — दुई पटक reflection भएपछि sight 90° ले मोडिन्छ।"},
      {q:"लेन्सको सामर्थ्यको dioptre एकाइमा नापिन्छ भने Focal length लाई कुन एकाइमा नापिन्छ ?", o:["मिटर", "सेन्टिमिटर", "मिलिमिटर", "माइक्रोमिटर"], a:0, e:"Lens को शक्ति dioptre (1/f) मा नापिन्छ, जहाँ focal length f लाई मिटर (metre) मा लिइन्छ।"},
      {q:"The angle between two plane mirrors of optical square, is", o:["20°", "45°", "60ᵍ", "both (b) and (c)"], a:1, e:"Optical square का दुई plane mirror बीच 45° को कोण हुन्छ। ⚠️ मूल विकल्प (c) '50ᵍ' थियो — 50 ᵍ = 45° भएकाले (b) र (d) 'both' दुवै सही ठहरिन्थे; (c) लाई 60ᵍ मा बदलिएको।"},
      {q:"Theodolite मा left face र right face किन लिइन्छ ?", o:["collimation error हटाउन", "collimation error घटाउन", "collimation error बढाउन", "collimation error नै हुँदैन"], a:0, e:"Left face र right face reading लिएर औसत गर्दा collimation error (र index error) हट्छ — error को चिह्न दुवै face मा उल्टो हुन्छ।"},
      {q:"Theodolite मा plate level axis र vertical axis को सम्बन्ध कस्तो हुन्छ ?", o:["एक आपसमा perpendicular", "एक आपसमा parellel", "एक आपसमा coincide", "एक आपसमा सम्बन्ध हुँदैन"], a:0, e:"Plate level axis र vertical axis आपसमा perpendicular हुनुपर्छ — plate bubble centred भएपछि vertical axis साँच्चै ठाडो हुन्छ।"},
      {q:"While rotating the theodolite in the horizontal plane, the bubble of the bubble tube takes up the same position in its tube, it indicates", o:["The rotation axis is vertical", "The trunnion axis is horizontal", "The line of collimation is perpendicular to vertical axis", "None of the above"], a:0, e:"तेर्सो रूपमा घुमाउँदा bubble ले एउटै position लिन्छ भने rotation axis vertical छ भन्ने बुझिन्छ — यो levelling को जाँच हो।"},
      {q:"Subtense bar is used to measure:", o:["Slope distance", "Horizontal distance", "Vertical distance", "None of the above"], a:1, e:"Subtense bar ले horizontal distance नाप्छ — bar लाई सधैं line सँग perpendicular (Q110) राखिन्छ; undulated area मा उपयोगी।"},
      {q:"लामो दुरी नाप्ने EDM मा कुन signal प्रयोग गरिन्छ ?", o:["Infrared", "Microwave", "Visible light", "All"], a:1, e:"लामो दूरी (100 km सम्म) को लागि microwave signal प्रयोग गरिन्छ (Tellurometer) — यो दिन र रात दुवैमा चल्छ।"},
      {q:"Axis of telescopic भन्नाले", o:["Object glass optical centre र cross wire जोड्ने रेखा", "Objective glass र eye piece को optical centre लाई जोड्ने रेखा", "Eye piece को centre र cross wire सम्म जोड्ने रेखा", "eye- piece को center र हरेक object सम्म जोड्ने रेखा"], a:0, e:"Object glass optical centre र cross wire जोड्ने रेखा"},
      {q:"In optical reading instruments", o:["The vertical circle is usually continuous from 0° to 359°", "The readings increase when the telescope is elevated in the face left position", "The readings decrease when the telescope is elevated in the face right position", "All the above"], a:3, e:"Optical reading instrument मा: vertical circle 0°–359° सम्म continuous हुन्छ, face left मा telescope उठाउँदा reading बढ्छ, र face right मा घट्छ — तीनै सही।"},
      {q:"The imaginary line passing through the intersection of cross hairs and the optical centre of the objective, is known as", o:["Line of sight", "Line of collimation", "Axis of the telescope", "None of these"], a:1, e:"Cross-hairs को intersection र objective को optical centre जोड्ने काल्पनिक रेखा = Line of collimation। यो axis of telescope सँग coincide हुनुपर्छ।"},
      {q:"Wild T₃ theodolite को Horizontal circle को diameter कति हुन्छ ?", o:["135mm", "135cm", "135dm", "None"], a:0, e:"Wild T₃ theodolite को horizontal circle को diameter 135 mm हुन्छ। ⚠️ मोडेल-विशिष्ट तथ्य — Wild को spec sheet बाट जाँच गर्नुहोला।"},
      {q:"Subtense bar बाट दुरी निकाल्ने सूत्र के हो ?", o:["s/ (tanθ₂ - tanθ₁)", "Ks sinθ - c sinθ", "D = S/2 cot θ/2", "माथिका सबै"], a:2, e:"D = (S/2) cot(θ/2), जहाँ S = subtense bar को लम्बाइ (सामान्यतया 2 m) र θ = bar ले instrument मा subtend गरेको कोण। ('Substance bar' टाइपो सुधार गरिएको।)"},
      {q:"The ratio of the angles subtended at the eye, by the virtual image and the object, is known as telescopes", o:["Resolving power", "Brightness", "Field of view", "Magnification"], a:3, e:"Virtual image ले आँखामा बनाएको कोण र object ले सिधै बनाएको कोण को अनुपात = Magnification (आवर्धन)।"},
      {q:"A theodolite can measure", o:["Difference in level", "Bearing of line", "Zenith angle", "All of the above"], a:3, e:"Theodolite ले difference in level (trigonometric levelling), bearing of line र zenith angle — तीनै नाप्न/निकाल्न सकिन्छ।"},
      {q:"Wild theodolite को shortest focusing distance कति हुन्छ ?", o:["०.० मीटर", "१.१ मीटर", "२.२ मीटर", "३.३ मीटर"], a:1, e:"Wild theodolite को shortest focusing distance करिब १.१ मिटर हुन्छ (यो भन्दा नजिक focusing हुँदैन)। ⚠️ मोडेल अनुसार फरक पर्न सक्छ।"},
      {q:"French cross staff बाट कति angle setout हुन्छ ?", o:["45⁰", "90⁰", "both A & B", "nither A nor B"], a:2, e:"French cross staff बाट 45° र 90° — दुवै कोण set out गर्न सकिन्छ (यसमा दुईवटा equal diameter का cylinder हुन्छन्, Q168)।"},
      {q:"Right angle set गर्न telescope भएको equipment कुन हो ?", o:["Prism square", "Site square", "Optical square", "Line ranger"], a:1, e:"Right angle set गर्न telescope सहितको उपकरण = Site square। Optical square/prism square मा telescope हुँदैन (ती हातले समात्ने साधन हुन्)। ⚠️ 'Site square' को प्रचलन आफ्नो स्रोत अनुसार जाँच गर्नुहोला।"},
      {q:"The real image of an object formed by the objective must lie", o:["In the plane of cross hairs", "At the centre of the telescope", "At the optical centre of the eye-piece", "Anywhere inside the telescope"], a:0, e:"Objective ले बनाएको real image cross-hairs को plane मा पर्नै पर्छ — नत्र parallax आउँछ (image ले cross-hair सँग सर्छ), जुन eye-piece र objective दुवै focusing गरेर हटाइन्छ।"},
      {q:"Line of collimanetion भन्नाले", o:["Cross wire को intersection र objective glass को optical centre बाट जाने काल्पनिक रेखा", "Eye-piece देखि cross wire जोड्ने काल्पनिक रेखा", "Eye-piece देखि object glass सम्म जोड्ने काल्पनिक रेखा", "माथिको सबै रेखाहरु"], a:0, e:"Cross wire को intersection र objective glass को optical centre बाट जाने काल्पनिक रेखा"},
      {q:"यान्त्रिक अनुलम्ब सूचकले theodolite के गर्नलाई सहयोग गर्छ ?", o:["Centering", "Levelling", "Orientation", "All of the above"], a:0, e:"यान्त्रिक अनुलम्ब सूचक (mechanical/optical plummet) ले theodolite लाई station माथि centring गर्न सहयोग गर्छ।"},
      {q:"The longitudinal section of the surface of bubble tube is", o:["Straight", "Circular", "parabolic", "Elliptic"], a:1, e:"Bubble tube को longitudinal section circular arc आकारको हुन्छ — त्यसैको radius of curvature ले bubble को sensitivity तय गर्छ।"},
      {q:"Sub-tense bar बाट कस्तो दुरी प्राप्त हुन्छ ?", o:["Slope distance", "vertical distance", "Horizontal distance", "All"], a:2, e:"Sub-tense bar बाट horizontal distance प्राप्त हुन्छ (D = S/2 cot θ/2)।"},
      {q:"Theodolite कुन कार्यमा प्रयोग हुने यन्त्र हो ?", o:["Horizontal angle नाप्न", "vertical angle नाप्न", "Bearing नाप्न", "माथिका सबै"], a:3, e:"Theodolite ले horizontal angle, vertical angle र bearing — सबै नाप्छ।"},
      {q:"Which are the fundamental lines of a Theodolite?", o:["3", "4", "5", "6"], a:1, e:"Theodolite का ४ वटा fundamental line हुन्: vertical axis, axis of plate level, line of collimation, र horizontal (trunnion) axis।"},
      {q:"The sensitivity of a bubble tube can be increased by", o:["increasing the diameter of the tube", "decreasing the length of bubble", "increasing the viscosity of liquid", "decreasing the radius of curvature of tube"], a:0, e:"Bubble tube को sensitivity बढाउन tube को diameter बढाइन्छ (radius of curvature ठूलो भएमा सानो ढलानले पनि bubble धेरै सर्छ)।"},
      {q:"Turnion axis ले कुन axis लाई बुझाउँछ ?", o:["horizontal axis", "vertical axis", "axis of telescope", "axis bubble tube"], a:0, e:"Trunnion axis = horizontal axis — telescope यसै वरिपरि ठाडो रूपमा घुम्छ।"},
      {q:"नेपालले दुरी नाप्न कुन धनबखम प्रयोग गर्दछ ?", o:["visible", "infrared", "micro wave", "all of above"], a:0, e:"⚠️ मूल स्टेम ('धनबखम') र key ('visible') दुवै अस्पष्ट छन् — 'तरङ्ग' (wave) अभिप्रेत देखिन्छ। नेपालको EDM/Total station मा सामान्यतया infrared (Distomat प्रकार) प्रयोग हुन्छ, visible होइन। key यथावत; आफ्नो स्रोत अनुसार सच्याउनुहोला।"},
      {q:"Theodolite मा index error को मान कतिको सम्मलाई बजअभुत गर्न सकिन्छ ?", o:["5ᵍ", "2ᶜᵍ", "200ᶜᵍ", "1ᶜᵍ"], a:0, e:"⚠️ Index error को सहनीय सीमा 5ᵍ (= 4.5°) भनिएको छ — यो व्यावहारिक (field) मापदण्डका लागि धेरै ठूलो देखिन्छ (Q206 मा ±5ᶜᶜᵍ)। एकाइ (ᵍ/ᶜᵍ/ᶜᶜᵍ) र मान Survey Department को निर्देशिकाबाट जाँच गर्नुहोला; key यथावत।"},
      {q:"A clinometers is used for", o:["Measuring angle of slope", "Correcting line of collimation", "Setting out right angles", "Defining natural features"], a:0, e:"Clinometer ढलानको कोण (angle of slope) नाप्न प्रयोग गरिन्छ। (Q126 को दोहोरो।)"},
      {q:"Removal of parallax, may be achieved by focusing", o:["The objective", "The eye- piece", "The objective and the eye- piece", "None of these"], a:2, e:"Parallax हटाउन eye-piece (cross-hair स्पष्ट) र objective (object स्पष्ट) — दुईटै focusing गर्नुपर्छ; एउटाले मात्र हुँदैन।"},
      {q:"यदि vernier को smallest division यसको primary scale को smallest division भन्दा लामो भएमा के भनिन्छ ?", o:["Direct vernier", "Double vernier", "Retrograde vernier", "Simple vernier"], a:2, e:"Vernier को smallest division primary scale को smallest division भन्दा लामो भए त्यसलाई Retrograde vernier भनिन्छ (graduations उल्टो दिशामा बढ्छन्)।"},
      {q:"स्टाफ भर्टिकल नभएमा हुने त्रुटी कुन रिडिङ्गले हट्छ ?", o:["V - Angle reading", "H - scale reading", "V - scale reading", "reading ले हट्दैन"], a:1, e:"⚠️ स्टाफ ठाडो नभएको error H-scale reading (तेर्सो पढाइ) बाट हट्छ भनिएको छ — staff नढल्किँदासम्म staff घुमाएर सबैभन्दा सानो/ठीक reading लिने अभ्यासलाई जनाउँछ। आफ्नो स्रोत अनुसार जाँच गर्नुहोला; key यथावत।"},
      {q:"If the smallest division of a vernier is longer than the smallest division of its primary scale, the vernier is known as", o:["Direct vernier", "Double vernier", "Retrograde vernier", "Simple vernier"], a:2, e:"Vernier को smallest division primary scale भन्दा लामो भए = Retrograde vernier। (Q165 को दोहोरो।)"},
      {q:"दुईवटा Equal diameter भएका cylinders consists भएको Cross staff कुन हो ?", o:["French", "Adjustable", "Open", "All"], a:0, e:"French cross staff मा दुईवटा equal diameter का cylinder हुन्छन् — यसबाट 45° र 90° set out गर्न सकिन्छ।"},
      {q:"The ratio of the distances at which a stated length can be distinguished by the telescope and the human eye, respectively, is called", o:["Brightness of telescope", "Magnification of telescope", "Resolving power of telescope", "None of these"], a:2, e:"Telescope र नाङ्गो आँखाले कुनै निश्चित लम्बाइ छुट्याउन सक्ने दूरीहरूको अनुपात = Resolving power of telescope।"},
      {q:"Subtense bar के को लागि प्रयोग गरिन्छ ?", o:["Levelling गर्न", "समतल क्षेत्रमा horizontal distances नाप्न", "undulated areas मा horizontal distances नाप्न", "angles नाप्न"], a:2, e:"undulated areas मा horizontal distances नाप्न"},
      {q:"Vertical plane of direct vertical distance नाप्न प्रयोग गरिने instrument लाई के भनिन्छ ?", o:["level", "chain", "staff", "tape"], a:2, e:"ठाडो plane मा सिधा ठाडो दूरी (direct vertical distance) नाप्न staff (levelling staff) प्रयोग गरिन्छ।"},
      {q:"The apparent error on reversal is", o:["Equal to the actual error", "Twice the actual error", "Thrice the actual error", "None of these"], a:1, e:"Reversal (face left/right) मा देखिने apparent error वास्तविक error को दोब्बर (twice) हुन्छ — त्यसैले error = apparent/2 र correction = apparent/2 उल्टो चिह्नमा।"},
      {q:"telescope inverted भन्नाले कुन position लाई बुझाउँछ ?", o:["right face", "bubble down", "A र B दुबै", "कुनै पनि होइन"], a:2, e:"Telescope inverted भन्नाले right face (bubble तल) — दुवै विवरण एउटै position जनाउँछन्।"},
      {q:"Tripod को butterfly screw नकसिनाले कस्तो error आउँछ ?", o:["Instrumental error", "Personal", "Natural", "Both A & B"], a:1, e:"Tripod को butterfly screw नकस्दा (ढिलो हुँदा) हुने error Personal error हो — यो यन्त्रको दोष होइन, परिचालकको लापरवाही हो।"},
      {q:"Theodolite मा मा रहेको horizontal slow-motion screw को काम के हो ?", o:["Horizontal wire लाई horizontally दायाँ बायाँ गर्नु", "Horizontal wire लाई vertically दायाँ बायाँ गर्नु", "Vertical wire लाई horizontally दायाँ बायाँ गर्नु", "Vertical wire लाई vertically दायाँ बायाँ गर्नु"], a:2, e:"Vertical wire लाई horizontally दायाँ बायाँ गर्नु"},
      {q:"Tellurometer ले signal को रुपमा कुन wave प्रयोग गर्दछ ?", o:["Visible light wave", "Infrared wave", "Microwave", "Long radio wave"], a:2, e:"Tellurometer ले microwave (high frequency radio wave) प्रयोग गर्छ — 100 km सम्म, दिन र रात दुवैमा, र दुईटा एउटै यन्त्र (master/remote) चाहिन्छ।"},
      {q:"Theodolite मा रहेको vertical slow-motion को काम के हो ?", o:["Horizontal wire लाई Horizontally तल माथि गर्नु", "Horizontal wire लाई vertically तल माथि गर्नु", "Vertical wire लाई Horizontally तल माथि गर्नु", "Vertical wire लाई vertically तल माथि गर्नु"], a:1, e:"Vertical slow-motion (tangent) screw ले horizontal wire लाई ठाडो रूपमा (vertically) माथि-तल सार्छ — vertical angle तेर्सो wire ले पढिन्छ।"},
      {q:"Graduation error हटाउन के गर्नु पर्दछ ?", o:["Left र Right face reading लिनुपर्छ", "बढि set reading लिनुपर्छ", "A र B दुबै", "कुनै पनि होइन"], a:2, e:"Graduation error हटाउन left–right face reading र धेरै set (different circle positions) दुवै लिनुपर्छ — graduation irregularity औसत हुन्छ।"},
      {q:"आफै उत्तर दक्षिण orientation गर्न सक्ने Theodolite कुन हो ?", o:["Mining theodolite", "Photo theodolite", "Astronomical theodolite", "Gyro theodolite"], a:3, e:"Gyro theodolite ले आफैं (gyroscope बाट) true north orientation पत्ता लगाउन सक्छ — भूमिगत mine survey मा अनिवार्य।"},
      {q:"Disomat ले signal को रुपमा कुन wave प्रयोग गर्दछ ?", o:["Visible light wave", "Infrared wave", "Microwave", "Long radio wave"], a:1, e:"Distomat ('Disomat' टाइपो) ले infrared wave प्रयोग गर्छ — short range करिब 3–5 km। तुलना: Geodimeter = visible light (medium), Tellurometer = microwave (long)। मूल key 'visible light' थियो, जुन Geodimeter (Q189) को हो। [testbook](https://testbook.com/question-answer/match-the-types-of-edm-instruments-with-wavelength--6a6b2d01368eaa60f8ada8af)"},
      {q:"Total station मा Tilt error ले कुन reading लाई बढी effect गर्दछ ?", o:["Horizontal reading", "Vertical reading", "Zenithal reading", "Height difference"], a:1, e:"Total station मा tilt error (vertical axis को compensation नमिल्दा) ले vertical reading (vertical angle) लाई बढी असर गर्छ — horizontal angle मा कम।"},
      {q:"Dumpy level मा रहेको level tube को sensitivity कति हुन्छ ?", o:["5\" per mm", "10\" per mm", "20\" per mm", "50\" per mm"], a:2, e:"Dumpy level को bubble tube को sensitivity करिब 20″ per mm (2 mm division) हुन्छ। ⚠️ मोडेल अनुसार फरक पर्न सक्छ।"},
      {q:"Telescopic alidade को accuracy कति हुन्छ ?", o:["Part per Ten", "Part per hundred", "Part per thousand", "Part per million"], a:2, e:"Telescopic alidade को accuracy करिब part per thousand (1/1000) हुन्छ। ⚠️ उपकरण अनुसार जाँच गर्नुहोला।"},
      {q:"Collimation line बवल दयूवको अक्षसंग सामानान्तर नहुनाले कुन त्रुटि हुन्छ ?", o:["व्यक्तिगत त्रुटि", "प्राकृतिक त्रुटि", "यान्त्रिक त्रुटि", "पारालेक्स त्रुटि"], a:2, e:"Collimation line bubble axis सँग समानान्तर नहुँदा यान्त्रिक त्रुटि (instrumental error) हुन्छ — यो permanent adjustment ले मिलाइन्छ, face left/right ले होइन। (मूल स्टेम 'बवल दयूवको अक्षसंग' टाइपोयुक्त थियो।)"},
      {q:"Vertical angle नाप्ने उपयुक्त समय कुन हो ?", o:["दिउँसो 1:30 - 3:30 सम्म", "विहान 5:00 - 7:30 सम्म", "बेलुका 5:30 - 7:30 सम्म", "जुनवेला नापेपनि हुन्छ"], a:1, e:"Vertical angle नाप्न बिहान 5:00–7:30 उपयुक्त मानिन्छ — घाम टाउकोमाथि हुँदा atmospheric refraction सबैभन्दा बढी हुन्छ। ⚠️ केही पाठ्यपुस्तकले refraction कम हुने भएर 'मध्यान्ह' सुझाउँछन् — आफ्नो स्रोत अनुसार मिलाउनुहोला; key यथावत।"},
      {q:"Dumpy level र Y-level का असल गुणहरु मिलाएर बनाएको level लाई के भनिन्छ ?", o:["Tilling level", "Cook's Reversible level", "Abney level", "Auto level"], a:1, e:"Dumpy level र Y-level का असल गुण मिलाएर बनेको level = Cook's Reversible level (अर्को नाम: Cushing's level)।"},
      {q:"T₃ theodolite मा vertical circle को graduation कति हुन्छ ?", o:["0ᵍ - 100ᵍ", "0ᵍ - 200ᵍ", "0ᵍ - 400ᵍ", "50ᵍ - 150ᵍ"], a:2, e:"T₃ theodolite को vertical circle 0ᵍ–400ᵍ (grad मा) graduated हुन्छ। (Degree मा भने 0°–360°)।"},
      {q:"तलका मध्ये कुन theodolite लाई Astronomical theodolite भनिन्छ ?", o:["Wild T₂", "Wild T₃", "Wild T₄", "Wild T₁₆"], a:2, e:"Astronomical theodolite = Wild T₄ — Wild को आफ्नै विवरण अनुसार T₄ 'geodetic triangulation, astronomical observations र geographical position determination' का लागि हो। Wild T₁₆ भने lowest-order survey (1 minute) को theodolite हो, astronomical होइन। [Wild Heerbrugg](https://www.wild-heerbrugg.shop/old/theodolites2.htm)"},
      {q:"Geodimeter ले signal को रुपमा कुन wave प्रयोग गर्दछ ?", o:["Visible light wave", "Infrared wave", "Microwave", "Long radio wave"], a:0, e:"Geodimeter ले visible light wave (modulated light) प्रयोग गर्छ — medium range, सुरुमा राती मात्र सीमित।"},
      {q:"Tilting level को least count कति हुन्छ ?", o:["1/5th of millimeter", "1/10th of millimeter", "1/50th of millimeter", "1/100th of millimeter"], a:2, e:"Tilting level को least count करिब 1/50th of a millimetre (bubble centring को सूक्ष्मता)। ⚠️ यो मान स्रोत अनुसार फरक पर्न सक्छ।"},
      {q:"Telescopic alidade मा लिइने H - Scale reading को unit के हो ?", o:["Meter", "Foot", "Yard", "None"], a:0, e:"Telescopic alidade मा H-scale reading को unit मिटर (metre) हुन्छ — H-scale ले horizontal distance सिधा मिटरमा दिन्छ (slope correction को लागि)।"},
      {q:"Horizontal angle नाप्ने उपयुक्त समय कुन हो ?", o:["विहान र साँझ", "दिउँसो", "राती", "जुनसुकै समयमा"], a:0, e:"Horizontal angle नाप्न बिहान र साँझ उपयुक्त — बीचको समयमा heat haze/refraction ले target को image हल्लिन्छ।"},
      {q:"Telescope को eye peace र objective peace आपसमा बदल्न सकिने level कुन हो ?", o:["cook's level", "Cushing's level", "Tilting level", "Y - level"], a:3, e:"Y-level (Wye level) मा telescope लाई Y-shaped support बाट निकालेर eye-piece र objective आपसमा साट्न (reverse) सकिन्छ — त्यसैले यसलाई reversible level पनि भनिन्छ।"},
      {q:"साधारण Telescopic alidade को Multiplicative constant कति हुन्छ ?", o:["25", "50", "75", "100"], a:3, e:"साधारण telescopic alidade को multiplicative constant k = 100 (stadia hair को अनुपात f/i) — additive constant c = 0।"},
      {q:"Chain survey मा प्रयोग गर्ने optical square को दुईवटा ऐना बीच कति डिग्रीको कोण बन्छ ?", o:["25°", "30°", "45°", "90°"], a:2, e:"Chain survey मा प्रयोग हुने optical square का दुई ऐना बीच 45° को कोण हुन्छ — double reflection ले 90° right angle दिन्छ।"},
      {q:"Theodolite मा Left face र Right face ready किन लिइन्छ ?", o:["Collimation error हटाउन", "Collimation error घटाउन", "माथिको A र B दुबै", "माथिको कुनै होइन"], a:0, e:"Collimation error हटाउन Left face र Right face reading लिइन्छ।"},
      {q:"Clinometer को मापन गर्नको लागि प्रयोग गरिन्छ ?", o:["उचाई", "दुरी", "कोण", "माथिका सबै"], a:2, e:"Clinometer कोण (angle of slope) मापन गर्न प्रयोग गरिन्छ — उचाइ/दूरी सिधा होइन (ती कोणबाट गणना गरिन्छ)।"},
      {q:"सामान्यतया चौथो दर्जाको Traverse को लागि कुन Theodolite प्रयोग गरिन्छ ?", o:["T2", "T1", "T0", "T16"], a:3, e:"चौथो दर्जा (fourth order) को traverse को लागि सामान्यतया Wild T16 (20″/1 minute direct reading) theodolite प्रयोग गरिन्छ — यो low-order traverse/mine/property survey को लागि हो। ⚠️ मूल विकल्पमा 'T2' दोहोरिएको थियो (a र b), जसले option array लाई अवैध बनाउँथ्यो — (b) लाई T1 मा सुधार गरिएको।"},
      {q:"Telescopic alidade र गर्दा H value किन लिइन्छ ?", o:["Vertical correction को लागि", "Horizontal correction को लागि", "Slope correction को लागि", "Distance correction को लागि"], a:2, e:"Telescopic alidade मा H value (H-scale reading) slope correction को लागि लिइन्छ — H-scale ले तेर्सो दूरी सिधा दिन्छ (ढल्केबाट तेर्सोमा लैजान)।"},
      {q:"Theodolite तलकामध्ये कुन कामको लागि प्रयोग गरिन्छ ?", o:["दुईवटा विन्दु बीचको दुरी नाप्न", "दुईवटा सर्मे रेखा बीचको क्षितिजीय कोण (Horizontal Angle) नाप्न", "नक्सा तयार गर्न", "माथिको कुनै होइन"], a:1, e:"दुईवटा सर्मे रेखा बीचको क्षितिजीय कोण (Horizontal Angle) नाप्न"},
      {q:"तल दिइएका कुराहरु मध्ये कुन Permanent adjustment भित्र पर्दैन ?", o:["Setting over the station", "Levelling up", "Elimination parallax", "All of the above"], a:3, e:"Setting over the station, levelling up र elimination of parallax — तीनै temporary adjustment हुन् (हरेक station मा गरिने), permanent adjustment होइनन्। त्यसैले सही उत्तर 'All of the above' हो; मूल key ले एउटा मात्र (setting over) रोजेको थियो।"},
      {q:"Levelling staff मा सबैभन्दा सानो Graduation कति हुन्छ ?", o:["1mm", "5mm", "5cm", "10cm"], a:1, e:"Levelling staff मा सबैभन्दा सानो graduation 5 mm हुन्छ (metric staff मा 5 mm सम्म अनुमान गरेर पढिन्छ)।"},
      {q:"E.D.M को full form के हुन्छ ?", o:["Electric Distance measurement", "Electronic Distance Measurement", "Electric Distomat", "Electronic Distomat"], a:1, e:"E.D.M = Electronic Distance Measurement (Measurement of Distance होइन, Measurement)।"},
      {q:"थियोडोलाइटमा Collimation line र Axis of telescope को सम्बन्ध कस्तो हुन्छ ?", o:["एक आपसमा लम्बपरेको", "एक आपसमा खटिएको", "एक आपसमा समानान्तर भएको", "एक आपसमा सोधा कोणमा रहेको"], a:1, e:"Collimation line र axis of telescope आपसमा coincide (खटिएको) हुनुपर्छ — यसै फाइलका Q88 र Q108 ले पनि 'coinciding' नै भन्छन्। मूल key 'लम्बपरेको' (perpendicular) यसै एकाइ भित्रको दुई item सँग बाझिन्थ्यो।"},
      {q:"Theodolite को graduated circle of lower plate को diameter कति हुन्छ ?", o:["2 to 5cm", "8 to 25cm", "30 to 40cm", "40 to 50cm"], a:1, e:"Theodolite को lower plate (horizontal circle) को graduated circle को diameter सामान्यतया 8 देखि 25 cm सम्म हुन्छ।"},
      {q:"Total station यन्त्रलाई standardization गर्वा index error को छुटफरक कति हुन्छ ?", o:["± 1ᶜᵍ", "± 5ᶜᵍ", "± 5ᶜᶜᵍ", "± 50ᶜᶜᵍ"], a:2, e:"⚠️ Total station standardization मा index error को अन्तर ±5ᶜᶜᵍ भनिएको छ — एकाइ (ᶜᶜᵍ) र मान Survey Department को निर्देशिकाबाट जाँच गर्नुहोला (Q162 सँग मेल खाँदैन)।"},
      {q:"तलका मध्ये कुन level instrument ले clinometer को पनि काम गर्न सक्दछ ?", o:["Dumpy level", "Tilting level", "Auto level", "Abney level"], a:3, e:"Abney level ले clinometer को पनि काम गर्छ — यसले ढलानको कोण (vertical angle) पनि नाप्न सक्छ।"},
      {q:"Telescopic alidade बाट कुन reading लिन सकिदैन ?", o:["H - Scale", "V - Scale", "Horizontal angle", "Vertical angle"], a:2, e:"Telescopic alidade बाट H-scale, V-scale र vertical angle पढ्न सकिन्छ, तर horizontal angle पढ्न सकिँदैन (यसमा horizontal graduated circle हुँदैन)।"},
      {q:"Optical square यन्त्रमा incident ray र reflected ray विचको angle कति हुन्छ ?", o:["45°", "45ᵍ", "90°", "90ᵍ"], a:2, e:"Optical square मा incident ray र reflected ray बीचको कोण 90° हुन्छ — दुई ऐना 45° मा राख्दा double reflection ले 90° deviation दिन्छ।"},
      {q:"Plumbob बाट तलका मध्ये कुन काम गर्न सकिदैन ?", o:["Centering गर्न", "Ranging गर्न", "Alidade check गर्न", "Orientation गर्न"], a:3, e:"Plumb bob बाट centring, ranging र alidade check गर्न सकिन्छ, तर orientation (दिशा मिलाउने) गर्न सकिँदैन — orientation को लागि compass/known line चाहिन्छ।"},
    ];
